11	#ifndef TIMG2COL_HPP
12	#define TIMG2COL_HPP
13	
14	namespace pto {
15	
16	template <SetFmatrixMode FmatrixMode = SetFmatrixMode::FMATRIX_A_AUTO>
17	PTO_INTERNAL void SetFmatrix(uint16_t fmapH, uint16_t fmapW, const uint8_t* padList)
18	{
19	    if constexpr (FmatrixMode == SetFmatrixMode::FMATRIX_A_AUTO || FmatrixMode == SetFmatrixMode::FMATRIX_B_AUTO) {
20	        uint64_t regFmatrix = 0;
21	        constexpr uint32_t l1ShiftBit = 16;
22	        regFmatrix |= uint64_t(fmapW & 0xFFFF);
23	        regFmatrix |= uint64_t(fmapH & 0xFFFF) << l1ShiftBit;
24	
25	        constexpr uint32_t padListShiftBit = 8;
26	        constexpr uint32_t padListShiftBase = 32;
27	        constexpr uint32_t padNumber = 4;
28	
29	        for (uint32_t i = 0; i < padNumber; i++) {
30	            regFmatrix |= uint64_t(padList[i] & 0xFF) << (padListShiftBase + i * padListShiftBit);
31	        }
32	        if constexpr (FmatrixMode == SetFmatrixMode::FMATRIX_A_AUTO) {
33	            set_fmatrix(regFmatrix);
34	        } else if constexpr (FmatrixMode == SetFmatrixMode::FMATRIX_B_AUTO) {
35	            set_fmatrix_b(regFmatrix);
36	        }
37	    }
38	}
39	
40	PTO_INTERNAL void SetRepeat(uint16_t repeatStride, uint8_t repeatTime, uint8_t repeatMode)
41	{
42	    constexpr uint32_t repeatTimeShiftBit = 16;
43	    constexpr uint32_t repeatModeShiftBit = 24;
44	    uint64_t rptConfig = 0;
45	    rptConfig |= uint64_t(repeatStride);
46	    rptConfig |= uint64_t(repeatTime) << repeatTimeShiftBit;
47	    rptConfig |= uint64_t(repeatMode) << repeatModeShiftBit;
48	    set_l3d_rpt(rptConfig);
49	}
50	
51	template <typename T>
52	PTO_INTERNAL void SetPadding(T padValue)
53	{
54	    constexpr uint16_t padValueShiftBit = 8;
55	    uint32_t paddingValue = 0;
56	    if constexpr (sizeof(T) == 1) {
57	        uint8_t u8Value = *reinterpret_cast<const uint8_t*>(&padValue);
58	        paddingValue = (static_cast<uint16_t>(u8Value) << padValueShiftBit) | u8Value;
59	    } else if constexpr (sizeof(T) == 2) {
60	        paddingValue = *reinterpret_cast<const uint16_t*>(&padValue);
61	    } else if constexpr (sizeof(T) == 4) {
62	        paddingValue = *reinterpret_cast<const uint32_t*>(&padValue);
63	    }
64	    set_padding(paddingValue);
65	}
66	
67	template <typename TileData, typename ConvTileData, SetFmatrixMode FmatrixMode>
68	__tf__ PTO_INTERNAL void TImg2col(
69	    typename TileData::TileDType __out__ dst, typename ConvTileData::TileDType __in__ src, uint16_t stepM,
70	    uint16_t stepK, uint16_t posM, uint16_t posK, uint8_t strideW, uint8_t strideH, uint16_t filterW, uint16_t filterH,
71	    uint8_t dilationW, uint8_t dilationH, bool transpose, uint16_t channelSize)
72	{
73	    using SrcType = std::conditional_t<(sizeof(typename ConvTileData::DType) == 2), half, typename ConvTileData::DType>;
74	    using DstType = std::conditional_t<(sizeof(typename TileData::DType) == 2), half, typename TileData::DType>;
75	    __cbuf__ SrcType* srcAddr = (__cbuf__ SrcType*)__cce_get_tile_ptr(src);
76	    __ca__ DstType* dstAddr = (__ca__ DstType*)__cce_get_tile_ptr(dst);
77	
78	    bool fmatrixCtrl =
79	        (FmatrixMode == SetFmatrixMode::FMATRIX_B_AUTO) || (FmatrixMode == SetFmatrixMode::FMATRIX_B_MANUAL);
80	
81	    bool highFilterW = (filterW > 255);
82	    bool highFilterH = (filterH > 255);
83	    uint8_t lowFilterW = filterW & 0xFF;
84	    uint8_t lowFilterH = filterH & 0xFF;
85	
86	    img2colv2_cbuf_to_ca(
87	        dstAddr, srcAddr, stepK, stepM, posK, posM, strideW, strideH, lowFilterW, lowFilterH, dilationW, dilationH,
88	        highFilterW, highFilterH, transpose, fmatrixCtrl, channelSize);
89	}
90	
91	template <typename TileData, typename ConvTileData, SetFmatrixMode FmatrixMode = SetFmatrixMode::FMATRIX_A_MANUAL>
92	PTO_INTERNAL void TIMG2COL_IMPL(TileData& dst, ConvTileData& src, uint16_t posM, uint16_t posK)
93	{
94	    static_assert((ConvTileData::Loc == TileType::Mat), "TImg2col: Source TileType only support Mat.");
95	    static_assert((TileData::Loc == TileType::Left), "TImg2col: Destination TileType only support Left.");
96	    static_assert(
97	        (ConvTileData::layout == Layout::NC1HWC0) || (ConvTileData::layout == Layout::NDC1HWC0),
98	        "TImg2col: Source layout only support NC1HWC0.");
99	    static_assert(
100	        TileData::SFractal == SLayout::RowMajor && TileData::isRowMajor,
101	        "TImg2col: Destination layout only support SLayout is RowMajor ang BLayout is RowMajor.");
102	    static_assert(
103	        std::is_same_v<typename ConvTileData::DType, typename TileData::DType>,
104	        "TImg2col: Destination and Source tile data types must be the same.");
105	    static_assert(
106	        std::is_same_v<typename TileData::DType, int8_t> || std::is_same_v<typename TileData::DType, half> ||
107	            std::is_same_v<typename TileData::DType, bfloat16_t> || std::is_same_v<typename TileData::DType, float>,
108	        "TImg2col: Invalid data type.");
109	    if constexpr (FmatrixMode == SetFmatrixMode::FMATRIX_A_AUTO || FmatrixMode == SetFmatrixMode::FMATRIX_B_AUTO) {
110	        SetFmatrix<FmatrixMode>(src.GetFmapH(), src.GetFmapW(), src.GetPadListArray());
111	        SetRepeat(src.GetRepeatStride(), src.GetRepeatTime(), src.GetRepeatMode());
112	        SetPadding(src.GetPadValue());
113	    }
114	    constexpr int32_t c0Size = BLOCK_BYTE_SIZE / sizeof(typename TileData::DType);
115	    uint16_t stepM = dst.GetValidRow();
116	    uint16_t stepK = CeilAlignment(dst.GetValidCol(), c0Size);
117	
118	    TImg2col<TileData, ConvTileData, FmatrixMode>(
119	        dst.data(), src.data(), stepM, stepK, posM, posK, src.GetStrideW(), src.GetStrideH(), src.GetFilterW(),
120	        src.GetFilterH(), src.GetDilationW(), src.GetDilationH(), src.GetTranspose(), src.GetChannelSize());
121	}
122	} // namespace pto
123	#endif // TIMG2COL_HPP
