15	using namespace pto;
16	constexpr uint32_t BUFFER_NUM = 2;
17	constexpr uint32_t L0_PINGPONG_BYTES = 32 * 1024; // L0A/L0B ping-pong split (32 KiB per buffer)
18	
19	template <typename T>
20	AICORE constexpr inline T CeilDivision(T num_1, T num_2)
21	{
22	    if (num_2 == 0) {
23	        return 0;
24	    }
25	    return (num_1 + num_2 - 1) / num_2;
26	}
27	template <typename T>
28	AICORE constexpr inline T Min(T num_1, T num_2)
29	{
30	    return num_1 < num_2 ? num_1 : num_2;
31	}
32	template <typename T>
33	AICORE constexpr inline T Max(T num_1, T num_2)
34	{
35	    return num_1 > num_2 ? num_1 : num_2;
36	}
37	template <typename OutTile, typename LeftTile, typename RightTile>
38	AICORE inline void MatmulAcc(OutTile cTile, LeftTile aTile, RightTile bTile, uint32_t kIter)
39	{
40	    if (kIter == 0) {
41	        TMATMUL(cTile, aTile, bTile);
42	    } else {
43	        TMATMUL_ACC(cTile, cTile, aTile, bTile);
44	    }
45	}
46	template <pipe_t srcPipe, pipe_t dstPipe>
47	AICORE inline void SetFlag(uint32_t id)
48	{
49	    set_flag(srcPipe, dstPipe, static_cast<event_t>(id));
50	}
51	template <pipe_t srcPipe, pipe_t dstPipe>
52	AICORE inline void WaitFlag(uint32_t id)
53	{
54	    wait_flag(srcPipe, dstPipe, static_cast<event_t>(id));
55	}
56	template <
57	    typename T, typename U, typename S, int n, uint32_t singleCoreN, uint32_t cin, uint32_t hin, uint32_t win,
58	    uint32_t c0, uint32_t hout, uint32_t wout>
59	AICORE inline void InitGMOffsets(
60	    __gm__ U*& currentSrc0, __gm__ S*& currentSrc1, __gm__ T*& currentDst, __gm__ T* out, __gm__ U* src0,
61	    __gm__ S* src1)
62	{
63	    // - Each core owns a contiguous C tile of shape [singleCoreM, singleCoreN].
64	    // - It reads the corresponding A panel [singleCoreM, K] and B panel [K, singleCoreN].
65	    constexpr uint32_t nIdex = n / singleCoreN;
66	    uint32_t mCoreIdx = get_block_idx() / nIdex; // get current launch core idx
67	    uint32_t nCoreIdx = get_block_idx() % nIdex;
68	    uint64_t gmOffsetA = mCoreIdx * cin * hin * win * c0;
69	    uint64_t gmOffsetB = nCoreIdx * c0 * singleCoreN;
70	    uint64_t gmOffsetC = mCoreIdx * n * hout * wout + nCoreIdx * singleCoreN * hout * wout;
71	    currentSrc0 = src0 + gmOffsetA;
72	    currentSrc1 = src1 + gmOffsetB;
73	    currentDst = out + gmOffsetC;
74	}
75	
76	template <
77	    typename T, typename U, typename S, uint32_t n, uint32_t baseM, uint32_t baseN, uint32_t hout, uint32_t wout,
78	    typename OutTile>
79	AICORE inline void StoreResult(OutTile cTile, __gm__ T* currentDst, uint32_t mIter, uint32_t nIter)
80	{
81	    // TSTORE stage: write the finished C tile [baseM, baseN] back to GM.
82	    SetFlag<PIPE_M, PIPE_FIX>(0);
83	    WaitFlag<PIPE_M, PIPE_FIX>(0);
84	
85	    constexpr int gStrideOut[5] = {n * hout * wout, hout * wout * 16, wout * 16, 16, 1};
86	    using ShapeDim5Out = pto::Shape<1, baseN / 16, CeilDivision(baseM, wout), wout, 16>;
87	    using StridDim5Out = pto::Stride<gStrideOut[0], gStrideOut[1], gStrideOut[2], gStrideOut[3], gStrideOut[4]>;
88	    using GlobalDataOut = GlobalTensor<T, ShapeDim5Out, StridDim5Out, Layout::NC1HWC0>;
89	
90	    GlobalDataOut dstGlobal(currentDst + mIter * baseM * gStrideOut[3] + nIter * baseN / 16 * gStrideOut[1]);
91	    TSTORE(dstGlobal, cTile);
92	
93	    SetFlag<PIPE_FIX, PIPE_M>(0);
94	    WaitFlag<PIPE_FIX, PIPE_M>(0);
95	}
96	
97	AICORE inline void InitSyncFlags()
98	{
99	    // supplement first sync instr for reverse sync in ProcessKIteration
100	    SetFlag<PIPE_MTE1, PIPE_MTE2>(0);
101	    SetFlag<PIPE_MTE1, PIPE_MTE2>(1);
102	    SetFlag<PIPE_M, PIPE_MTE1>(0);
103	    SetFlag<PIPE_M, PIPE_MTE1>(1);
104	}
105	
106	AICORE inline void WaitSyncFlags()
107	{
108	    // supplement last sync instr for reverse sync in ProcessKIteration
109	    WaitFlag<PIPE_M, PIPE_MTE1>(0);
110	    WaitFlag<PIPE_M, PIPE_MTE1>(1);
111	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(0);
112	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(1);
113	}
114	template <
115	    uint32_t baseK, uint32_t stepKa, uint32_t stepKb, typename TileMatAData, typename TileMatBData, typename LeftTile,
116	    typename RightTile, typename ResTile>
117	AICORE inline void MacroMatmul(
118	    uint32_t kIter, uint8_t currMte2Idx, uint8_t mte1DBFlag, TileMatAData fmapMat[BUFFER_NUM],
119	    TileMatBData weightMat[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM], ResTile& cTile,
120	    uint32_t woutStart)
121	{
122	    const uint32_t kModStepKa = kIter % stepKa;
123	    // Wait until TMATMUL is done with the current L0A/L0B buffer before overwriting it via TEXTRACT.
124	    WaitFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
125	
126	    // TEXTRACT stage: slice the loaded L1 panel into the baseK chunk we need this iteration.
127	    if (kModStepKa == 0)
128	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(0);
129	    TIMG2COL(aTile[mte1DBFlag], fmapMat[currMte2Idx], woutStart, kModStepKa * baseK);
130	    if (kModStepKa == 0)
131	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(1);
132	    TEXTRACT(bTile[mte1DBFlag], weightMat[currMte2Idx], (kIter % stepKb) * baseK, 0);
133	
134	    if ((kIter + 1) % stepKa == 0) {
135	        // Allow the next TLOAD to reuse this L1 slot.
136	        SetFlag<PIPE_MTE1, PIPE_MTE2>(currMte2Idx);
137	    }
138	
139	    // TMATMUL stage: compute (or accumulate) into cTile.
140	    SetFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
141	    WaitFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
142	    MatmulAcc(cTile, aTile[mte1DBFlag], bTile[mte1DBFlag], kIter);
143	    // Signal that TMATMUL is done, so the next iteration may TEXTRACT into the other ping-pong slot.
144	    SetFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
145	}
146	template <
147	    typename U, uint32_t cin, uint32_t hin, uint32_t win, uint32_t c0, uint32_t n, uint32_t channelSize, uint32_t hk,
148	    uint32_t wk, uint32_t baseK, uint32_t baseN, uint32_t stepKa, uint32_t stepKb, typename TileMatAData,
149	    typename TileMatBData, typename LeftTile, typename RightTile, typename ResTile>
150	AICORE inline void ProcessKIteration(
151	    __gm__ U* currentSrc0, __gm__ U* currentSrc1, uint32_t hinStart, uint32_t hinCount, uint32_t woutStart,
152	    uint32_t kIter, uint32_t nIter, TileMatAData fmapMat[BUFFER_NUM], TileMatBData weightMat[BUFFER_NUM],
153	    LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM], ResTile& outTile, uint8_t& mte2DBFlag, uint8_t& mte1DBFlag)
154	{
155	    constexpr int gStrideSrc0[5] = {cin * hin * win * c0, hin * win * c0, win * c0, c0, 1};
156	    using ShapeDim5Src0 = pto::Shape<1, channelSize / c0, -1, win, c0>;
157	    using StridDim5Src0 = pto::Stride<gStrideSrc0[0], gStrideSrc0[1], gStrideSrc0[2], gStrideSrc0[3], gStrideSrc0[4]>;
158	    using GlobalDataSrc0 = GlobalTensor<U, ShapeDim5Src0, StridDim5Src0, Layout::NC1HWC0>;
159	
160	    constexpr int gStrideSrc1[5] = {cin * hk * wk * n * c0, n * c0, 16 * c0, c0, 1};
161	    using ShapeDim5Src1 = pto::Shape<1, stepKb * baseK / c0, baseN / 16, 16, c0>;
162	    using StridDim5Src1 = pto::Stride<gStrideSrc1[0], gStrideSrc1[1], gStrideSrc1[2], gStrideSrc1[3], gStrideSrc1[4]>;
163	    using GlobalDataSrc1 = GlobalTensor<U, ShapeDim5Src1, StridDim5Src1, Layout::FRACTAL_Z>;
164	
165	    const uint32_t kModStepKa = kIter % stepKa;
166	
167	    if (kModStepKa == 0) {
168	        GlobalDataSrc0 fmap(
169	            currentSrc0 + (kIter * baseK) / (hk * wk * c0) * gStrideSrc0[1] + hinStart * gStrideSrc0[2],
170	            pto::Shape<1, channelSize / c0, -1, win, c0>(hinCount));
171	        GlobalDataSrc1 weight(
172	            currentSrc1 + (kIter * baseK / c0) * gStrideSrc1[1] + (nIter * baseN / 16) * gStrideSrc1[2]);
173	        WaitFlag<PIPE_MTE1, PIPE_MTE2>(mte2DBFlag);
174	        TLOAD(fmapMat[mte2DBFlag], fmap);
175	        SetFlag<PIPE_MTE2, PIPE_MTE1>(0);
176	        TLOAD(weightMat[mte2DBFlag], weight);
177	        SetFlag<PIPE_MTE2, PIPE_MTE1>(1);
178	        mte2DBFlag = (mte2DBFlag == 0) ? 1 : 0;
179	    }
180	    const uint32_t currMte2Idx = (mte2DBFlag == 0) ? 1 : 0; // mte2DBFlag reversed
181	
182	    MacroMatmul<baseK, stepKa, stepKb>(
183	        kIter, currMte2Idx, mte1DBFlag, fmapMat, weightMat, aTile, bTile, outTile, woutStart);
184	    mte1DBFlag = (mte1DBFlag == 0) ? 1 : 0;
185	}
186	template <
187	    typename T, typename U, uint32_t blockDim, uint32_t m, uint32_t k, uint32_t n, uint32_t singleCoreM,
188	    uint32_t singleCoreK, uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM,
189	    uint32_t stepKa, uint32_t stepKb, uint32_t stepN, uint32_t batch, uint32_t cin, uint32_t hin, uint32_t win,
190	    uint32_t c0, uint32_t hk, uint32_t wk, uint32_t hout, uint32_t wout, uint32_t channelSize, typename ResTile,
191	    uint32_t strideH = 1, uint32_t padTop = 1, typename TileMatAData, typename TileMatBData, typename LeftTile,
192	    typename RightTile>
193	
194	AICORE inline void Compute(
195	    __gm__ U* currentSrc0, __gm__ U* currentSrc1, __gm__ T*& currentDst, TileMatAData fmapMat[BUFFER_NUM],
196	    TileMatBData weightMat[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM])
197	{
198	    constexpr uint32_t tailValidM = singleCoreM % baseM;
199	    constexpr uint32_t mLoop = CeilDivision(singleCoreM, baseM);
200	    constexpr uint32_t nLoop = CeilDivision(singleCoreN, baseN);
201	    constexpr uint32_t kLoop = CeilDivision(singleCoreK, baseK);
202	    uint8_t mte2DBFlag = 0, mte1DBFlag = 0;
203	
204	    for (uint32_t mIter = 0; mIter < mLoop; mIter++) {
205	        int64_t mStart = mIter * baseM;
206	        int64_t mCount = Min<int64_t>(baseM, hout * wout - mStart);
207	        int64_t mEnd = mStart + mCount - 1;
208	        int64_t houtStart = mStart / wout;
209	        int64_t woutStart = mStart % wout;
210	        int64_t houtEnd = mEnd / wout;
211	        int64_t hinStart = Max<int64_t>(0, houtStart * strideH - padTop);
212	        int64_t hinEnd = Min<int64_t>(houtEnd * strideH - padTop + (hk - 1), hin - 1);
213	        int64_t hinCount = hinEnd - hinStart + 1;
214	        uint32_t currentM = (mIter == mLoop - 1 && tailValidM > 0) ? tailValidM : baseM;
215	        for (int i = 0; i < BUFFER_NUM; ++i) {
216	            aTile[i] = LeftTile(currentM);
217	            fmapMat[i] = TileMatAData(hinCount);
218	            fmapMat[i].SetFmapH(hinCount);
219	            fmapMat[i].SetFmapW(win);
220	            fmapMat[i].SetChannelSize(channelSize);
221	            fmapMat[i].SetFilterH(3);
222	            fmapMat[i].SetFilterW(3);
223	            fmapMat[i].SetPadList(0, 1);
224	            fmapMat[i].SetPadList(1, 1);
225	            fmapMat[i].SetPadList(2, Max<int64_t>(0, padTop - houtStart * strideH));
226	            fmapMat[i].SetPadList(3, Max<int64_t>(0, (houtEnd + hk) * strideH - hin - padTop));
227	        }
228	        ResTile outTile(currentM);
229	        TASSIGN(outTile, 0x0);
230	        SETFMATRIX(fmapMat[0]);
231	        TASSIGN(fmapMat[0], 0x0);
232	        TASSIGN(fmapMat[1], 0x0 + channelSize * win * (hinCount + (hk - 1)) * sizeof(U));
233	        for (uint32_t nIter = 0; nIter < nLoop; nIter++) {
234	            for (uint32_t kIter = 0; kIter < kLoop; kIter++) {
235	                ProcessKIteration<U, cin, hin, win, c0, n, channelSize, hk, wk, baseK, baseN, stepKa, stepKb>(
236	                    currentSrc0, currentSrc1, hinStart, hinCount, woutStart, kIter, nIter, fmapMat, weightMat, aTile,
237	                    bTile, outTile, mte2DBFlag, mte1DBFlag);
238	            }
239	            StoreResult<T, U, U, n, baseM, baseN, hout, wout>(outTile, currentDst, mIter, nIter);
240	        }
241	    }
242	}
243	template <
244	    typename T, typename U, typename S, uint32_t blockDim, uint32_t m, uint32_t k, uint32_t n, uint32_t singleCoreM,
245	    uint32_t singleCoreK, uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM,
246	    uint32_t stepKa, uint32_t stepKb, uint32_t stepN, uint32_t batch, uint32_t cin, uint32_t hin, uint32_t win,
247	    uint32_t c0, uint32_t hk, uint32_t wk, uint32_t hout, uint32_t wout, uint32_t strideH = 1, uint32_t strideW = 1,
248	    uint32_t dilationH = 1, uint32_t dilationW = 1, uint32_t padTop = 1, uint32_t padBottom = 1, uint32_t padLeft = 1,
249	    uint32_t padRight = 1>
250	AICORE inline void RunConv2dForward(__gm__ T* out, __gm__ U* src0, __gm__ S* src1)
251	{
252	    __gm__ U* currentSrc0 = nullptr;
253	    __gm__ S* currentSrc1 = nullptr;
254	    __gm__ T* currentDst = nullptr;
255	    InitGMOffsets<T, U, S, n, singleCoreN, cin, hin, win, c0, hout, wout>(
256	        currentSrc0, currentSrc1, currentDst, out, src0, src1);
257	    constexpr uint32_t channelSize = CeilDivision(stepKa * baseK, hk * wk);
258	    constexpr int bufferSizeA = sizeof(U) * channelSize * win * (CeilDivision(baseM, wout) + (hk - 1));
259	    using TileMatAData =
260	        ConvTile<TileType::Mat, U, bufferSizeA, Layout::NC1HWC0, pto::ConvTileShape<1, channelSize / c0, -1, win, c0>>;
261	    TileMatAData fmapMat[BUFFER_NUM];
262	
263	    constexpr int bufferSizeB = stepKb * baseK * baseN * sizeof(U);
264	    using TileMatBData = ConvTile<
265	        TileType::Mat, U, bufferSizeB, Layout::FRACTAL_Z, pto::ConvTileShape<stepKb * baseK / c0, baseN / 16, 16, c0>>;
266	    TileMatBData weightMat[BUFFER_NUM];
267	    TASSIGN(weightMat[0], 0x20000);
268	    TASSIGN(weightMat[1], 0x20000 + baseK * baseN * stepKb * sizeof(U));
269	
270	    using LeftTile = TileLeft<U, baseM, baseK, -1, baseK>;
271	    using RightTile = TileRight<S, baseK, baseN, baseK, baseN>;
272	    using ResTile = TileAccCompact<float, baseM, baseN, -1, baseN>;
273	    LeftTile aTile[BUFFER_NUM];
274	    RightTile bTile[BUFFER_NUM];
275	
276	    TASSIGN(aTile[0], 0x0);                     // L0A ping
277	    TASSIGN(aTile[1], 0x0 + L0_PINGPONG_BYTES); // L0A pang
278	    TASSIGN(bTile[0], 0x0);                     // L0B ping
279	    TASSIGN(bTile[1], 0x0 + L0_PINGPONG_BYTES); // L0B pang
280	
281	    InitSyncFlags();
282	    Compute<
283	        half, half, blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, stepM, stepKa,
284	        stepKb, stepN, batch, cin, hin, win, c0, hk, wk, hout, wout, channelSize, ResTile>(
285	        currentSrc0, currentSrc1, currentDst, fmapMat, weightMat, aTile, bTile);
286	    WaitSyncFlags();
287	}
288	
289	template <
290	    typename T, uint32_t blockDim, uint32_t m, uint32_t k, uint32_t n, uint32_t singleCoreM, uint32_t singleCoreK,
291	    uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM, uint32_t stepKa,
292	    uint32_t stepKb, uint32_t stepN, uint32_t batch, uint32_t cin, uint32_t hin, uint32_t win, uint32_t c0, uint32_t hk,
293	    uint32_t wk, uint32_t hout, uint32_t wout, uint32_t strideH = 1, uint32_t strideW = 1, uint32_t dilationH = 1,
294	    uint32_t dilationW = 1, uint32_t padTop = 1, uint32_t padBottom = 1, uint32_t padLeft = 1, uint32_t padRight = 1>
295	__global__ AICORE void Conv2dForward(__gm__ uint8_t* out, __gm__ uint8_t* src0, __gm__ uint8_t* src1)
296	{
297	    RunConv2dForward<
298	        half, half, half, blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, stepM, stepKa,
299	        stepKb, stepN, batch, cin, hin, win, c0, hk, wk, hout, wout>(
300	        reinterpret_cast<__gm__ half*>(out), reinterpret_cast<__gm__ half*>(src0),
301	        reinterpret_cast<__gm__ half*>(src1));
302	}
303	
304	#ifndef __COSTMODEL
305	template <typename T>
306	void launchConv2dForward(uint8_t* out, uint8_t* src0, uint8_t* src1, void* stream)
307	{
308	    constexpr uint32_t blockDim = 24;
309	    constexpr uint32_t m = 6144;
310	    constexpr uint32_t n = 6144;
311	    constexpr uint32_t k = 4608;
312	    constexpr uint32_t singleCoreM = 1536;
313	    constexpr uint32_t singleCoreN = 1024;
314	    constexpr uint32_t singleCoreK = 4608;
315	    constexpr uint32_t baseM = 128;
316	    constexpr uint32_t baseK = 48;
317	    constexpr uint32_t baseN = 256;
318	
319	    constexpr uint32_t stepM = 1;
320	    constexpr uint32_t stepKa = 3;
321	    constexpr uint32_t stepKb = 3;
322	    constexpr uint32_t stepN = 1;
323	
324	    constexpr uint32_t batch = 4;
325	    constexpr uint32_t cin = 32;
326	    constexpr uint32_t hin = 16;
327	    constexpr uint32_t win = 96;
328	    constexpr uint32_t c0 = 16;
329	    constexpr uint32_t hk = 3;
330	    constexpr uint32_t wk = 3;
331	    constexpr uint32_t strideH = 1;
332	    constexpr uint32_t strideW = 1;
333	    constexpr uint32_t dilationH = 1;
334	    constexpr uint32_t dilationW = 1;
335	    constexpr uint32_t padTop = 1;
336	    constexpr uint32_t padBottom = 1;
337	    constexpr uint32_t padLeft = 1;
338	    constexpr uint32_t padRight = 1;
339	    constexpr uint32_t hout = (hin + padTop + padBottom - dilationH * (hk - 1) - 1) / strideH + 1;
340	    constexpr uint32_t wout = (win + padLeft + padRight - dilationW * (wk - 1) - 1) / strideW + 1;
341	    Conv2dForward<
342	        T, blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, stepM, stepKa, stepKb, stepN,
343	        batch, cin, hin, win, c0, hk, wk, hout, wout><<<blockDim, nullptr, stream>>>(out, src0, src1);
344	}
345	template void launchConv2dForward<uint16_t>(uint8_t* out, uint8_t* src0, uint8_t* src1, void* stream);
346	#endif
