            shape[0] = n1;
        if constexpr (staticShape[1] == DYNAMIC)
            shape[1] = n2;
        if constexpr (staticShape[2] == DYNAMIC)
            shape[2] = n3;
        if constexpr (staticShape[3] == DYNAMIC)
            shape[3] = n4;
        if constexpr (staticShape[4] == DYNAMIC)
            shape[4] = n5;
        if constexpr (staticShape[5] == DYNAMIC)
            shape[5] = n6;
