        if constexpr (staticShape[1] == DYNAMIC)
            shape[1] = 1;
        if constexpr (staticShape[2] == DYNAMIC)
            shape[2] = 1;
        if constexpr (staticShape[3] == DYNAMIC)
            shape[3] = 1;
