    PTO_INTERNAL void SetFilterH(uint16_t filterH) { filterH_ = filterH; }
    PTO_INTERNAL uint16_t GetFilterW() const { return filterW_; }
    PTO_INTERNAL void SetFilterW(uint16_t filterW) { filterW_ = filterW; }
