    if (strideH != 0 && strideW != 0) {
        heightOut = (fmapH + padTop + padBottom - dilationH * (hk - 1) - 1) / strideH + 1;
        widthOut = (fmapW + padLeft + padRight - dilationW * (wk - 1) - 1) / strideW + 1;
    }
    size_t aFileSize = fmapN * fmapC1 * fmapH * fmapW * fmapC0 * sizeof(U);
